var checks=new List<object>();var passed=0;var failed=0;
void Require(bool condition){if(!condition)throw new InvalidOperationException("Contract assertion failed.");}
async Task Check(string name,Func<Task> body){try{await body();checks.Add(new{name,passed=true});passed++;}catch(Exception error){checks.Add(new{name,passed=false,error=error.GetType().FullName,message=error.Message});failed++;}}
async Task<T> Throws<T>(Func<Task> body)where T:Exception{try{await body();throw new InvalidOperationException("Expected exception.");}catch(T error){return error;}}
void Throwing<T>(Action body)where T:Exception{try{body();throw new InvalidOperationException("Expected exception.");}catch(T){}}
TenantChangeAuditPolicy Policy(TenantChangeAuditMode mode=TenantChangeAuditMode.ChangedFields,bool empty=false)=>new(mode,[new("document.update","write","document",empty?[]:[new("title"),new("secret",true)])]);
TenantChangeStates States()=>new(new([KeyValuePair.Create("title",TenantChangeValue.Text("old")),KeyValuePair.Create("secret",TenantChangeValue.Text("private-before"))]),new([KeyValuePair.Create("title",TenantChangeValue.Text("new")),KeyValuePair.Create("secret",TenantChangeValue.Text("private-after"))]));
TenantChangeReceipt Receipt(TenantOperationContext c,string? mutation=null,Guid? id=null)=>new(id??Guid.NewGuid(),mutation=="principal"?new("issuer","other"):c.Identity.Principal,mutation=="scheme"?"Other":c.Identity.AuthenticationScheme,mutation=="tenant"?new("B"):c.Tenant,mutation=="operation"?"other.read":c.OperationId,mutation=="action"?"read":c.Action,mutation=="kind"?"other":c.Resource.Kind,mutation=="entity"?"other":c.Resource.ResourceId,mutation=="acl"?"other":c.Resource.Version,TenantChangeKind.Update,"v1","v2");
TenantChangeAuditOutboxExecutor<IBusinessSession> Executor(Fixture f,Provider p,TenantChangeAuditPolicy? policy=null,TimeSpan? timeout=null)=>TenantChangeAuditOutboxExecutor<IBusinessSession>.ActivateValidated(policy??Policy(),f.Registry,["document.update"],()=>p,timeout,f.Clock)!;
ValueTask<TenantChangeAuditMutation<int>> Mutate(IBusinessSession s,TenantOperationContext c,Func<TenantChangeStates>? states=null){s.Mutate();return ValueTask.FromResult(new TenantChangeAuditMutation<int>(Receipt(c),7,states??States));}
async Task<TenantChangeAuditTransactionException> TxFailure(Func<Task> body,TenantChangeAuditTransactionOutcome outcome){var e=await Throws<TenantChangeAuditTransactionException>(body);Require(e.Outcome==outcome&&e.MayHaveCommitted==(outcome is not(TenantChangeAuditTransactionOutcome.NotStarted or TenantChangeAuditTransactionOutcome.RolledBack)));return e;}

